settings._cssCustom:
.blog-archive-intro__search .bricks-search-form {
	gap: 1.5rem;
}
.blog-archive-intro__search [type="search"] {
	width: 70% !important;
}
.blog-archive-intro__search [type="submit"] {
	background-color: var(--primary);
  color: var(--white);
  width: 30%;
  padding: 10px 15px;
  text-align: center;
  height: auto;
  position: static!important;
  clip-path: unset !important;
}
.blog-archive-intro__search [type="submit"]:focus {
	border-radius: 0;
  box-shadow: none;
  font-size: 100%;
  font-weight: 400;
  line-height: 100%;
  outline: none;
  padding: 10px;
  text-align: center;
  clip-path: unset;
}
.blog-archive-intro__search [type="submit"] span {
	height: auto;
  position: static!important;
  width: auto;
}

.blog-archive-9-wrapper {
	display: grid;
	grid-template-columns: repeat(2, 1fr);
  gap: var(--grid-gap);
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) {
	grid-area: 1 / 1 / 4 / 2;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  grid-template-rows: repeat(1, minmax(0, 1fr));
  align-items: flex-start;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__thumb {
	height: 100%;
  width: 100%;
  aspect-ratio: 4/6 !important;

}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__title {
	font-size: calc( var(--text-xxl) + .2rem );
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__read {
	padding: 1.2rem 2.1rem !important;
  color: var(--white);
  background-color: var(--primary);
  gap: 0;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__read i::before {
	display: none;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(2) {
	grid-area: 1 / 2 / 2 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(3) {
	grid-area: 2 / 2 / 3 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(4) {
	grid-area: 3 / 2 / 4 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(5) {
	grid-area: 4 / 1 / 5 / 2;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(6) {
	grid-area: 4 / 2 / 5 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(7) {
	grid-area: 5 / 1 / 6 / 2;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(8) {
	grid-area: 5 / 2 / 6 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:not(:first-child) .blog-archive-9-card__excerpt {
	display: none;
}

settings._cssCustom:mobile_landscape:
.blog-archive-9-wrapper {
	display: grid;
	grid-template-columns: repeat(1, 1fr);
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) {
	grid-area: 1 / 1 / 2 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__thumb {
	height: 20rem;
  width: 100%;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__title {
	font-size: var(--text-xl);
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__read {
	padding: 0 !important;
  color: var(--base);
  background-color: transparent;
  gap: 1rem;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(1) .blog-archive-9-card__read i::before {
	display: block;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(2) {
	grid-area: 2 / 1 / 3 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(3) {
	grid-area: 3 / 1 / 4 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(4) {
	grid-area: 4 / 1 / 5 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(5) {
	grid-area: 5 / 1 / 6 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(6) {
	grid-area: 6 / 1 / 7 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(7) {
	grid-area: 7 / 1 / 8 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:nth-child(8) {
	grid-area: 8 / 1 / 9 / 3;
}
.blog-archive-9-wrapper .blog-archive-9-card:not(:first-child) .blog-archive-9-card__excerpt {
	display: block;
}
